from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class Alarm(SchemaObject):
    uuid = SchemaField(name='uuid', not_null=True)
    severity = SchemaField(name='severity', not_null=True)
    alarm_id = SchemaField(name='alarm_id', not_null=True)
    alarm_name = SchemaField(name='alarm_name', not_null=True)
    fault_id = SchemaField(name='fault_id', not_null=True)
    fault_name = SchemaField(name='fault_name', not_null=True)

    def __init__(self, uuid, severity, alarm_id, alarm_name, fault_id, fault_name):
        self.uuid = uuid
        self.severity = severity
        self.alarm_id = alarm_id
        self.alarm_name = alarm_name
        self.fault_id = fault_id
        self.fault_name = fault_name

        super(Alarm, self).__init__()
